css.content:
/* Popover, dropdown menu and select content on Radix: a bordered panel above the page. */
.popover { z-index: var(--z-drawer); min-width: 200px; max-width: min(360px, 92vw); padding: var(--s4); background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.popover:focus-visible { outline-offset: 2px; }
.menu-content { z-index: var(--z-drawer); min-width: 200px; padding: var(--s1) 0; background: var(--background); color: var(--foreground); border: 1px solid var(--foreground); animation: dialog-fade var(--fast) var(--ease); }
.menu-content .menu-item { cursor: pointer; }
.menu-content .menu-item[data-highlighted] { background: var(--foreground); color: var(--background); outline: none; }
.menu-content .menu-item[data-disabled] { opacity: 0.5; pointer-events: none; }
.menu-content .menu-item[data-variant="danger"][data-highlighted] { background: var(--danger); }
.menu-label { padding: var(--s2) var(--s4); font-size: var(--text-xs); text-transform: uppercase; letter-spacing: 0.08em; color: var(--muted); }
.menu-indicator { width: 14px; display: inline-flex; justify-content: center; }
.menu-item-check { display: flex; align-items: center; gap: var(--s3); }

source.content:
import {forwardRef, type ComponentPropsWithoutRef, type ElementRef} from 'react';
import {HoverCard as Radix} from 'radix-ui';
import {cx} from '../../utils/cx';

/** The root of a card that shows extra detail when its trigger is hovered or focused. Put a `HoverCardTrigger` and `HoverCardContent` inside. */
export const HoverCard = Radix.Root;
/** The element (usually a link) that shows the card on hover or focus; use `asChild` to render your own element. */
export const HoverCardTrigger = Radix.Trigger;

/** The floating card, rendered in a portal. Opens 8px from the trigger, aligned to its start. Keep it supplementary: it is not reachable by touch. */
export const HoverCardContent = forwardRef<ElementRef<typeof Radix.Content>, ComponentPropsWithoutRef<typeof Radix.Content>>(function HoverCardContent({className, sideOffset = 8, align = 'start', ...rest}, ref) {
  return (
    <Radix.Portal>
      <Radix.Content ref={ref} sideOffset={sideOffset} align={align} className={cx('popover', className)} {...rest} />
    </Radix.Portal>
  );
});
